from pathlib import Path
import json,collections,math,numpy as np
R=Path.cwd();j=json.loads((R/'build/graphics/current_size_choices_r71/manifest.json').read_text());families={e['family']:e for e in j['records']if not e['heldForEvaluation']};keys=['brightness','contrast','saturation','gamma'];levels=collections.defaultdict(list)
